  --typing-radius: 16px;
  --typing-dot-color: rgba(255, 255, 255, 0.4);

  /* ===== 翻译：按钮隐藏但功能在 ===== */
  --translation-always-show: 0;
  --translation-btn-display: inline-flex;
  --translation-btn-opacity: 0;
  --translation-btn-color: rgba(255, 255, 255, 0.5);
  --translation-text-color: rgba(255, 255, 255, 0.7);
  --translation-bg: rgba(255, 255, 255, 0.06);

  /* ===== 引用 ===== */
  --reply-detached-bg: transparent;
  --reply-detached-border-left: none;
  --reply-detached-border: none;
  --reply-detached-radius: 0;
  --reply-detached-padding: 2px 4px;
  --reply-detached-shadow: none;
  --reply-detached-text-color: rgba(255, 255, 255, 0.45);
  --reply-detached-name-color: rgba(255, 255, 255, 0.55);
  --reply-detached-max-width: 85%;
  --reply-detached-margin-bottom: 2px;

  /* ===== 系统消息 ===== */
  --system-msg-bg: rgba(255, 255, 255, 0.04);
  --system-msg-color: rgba(255, 255, 255, 0.35);

  /* ===== 菜单 ===== */
  --reaction-bar-bg: rgba(20, 20, 20, 0.8);
  --reaction-bar-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
  --context-menu-bg: rgba(20, 20, 20, 0.85);
  --context-menu-blur: 30px;
  --context-menu-shadow: 0 8px 30px rgba(0, 0, 0, 0.3);

  /* ===== 简介卡 ===== */
  --profile-card-name-color: #ffffff;
  --profile-card-subtitle-color: rgba(255, 255, 255, 0.5);
  --profile-card-btn-bg: rgba(255, 255, 255, 0.06);
  --profile-card-btn-color: rgba(255, 255, 255, 0.7);
  --profile-card-avatar-border: 1px solid rgba(255, 255, 255, 0.1);
  --profile-card-avatar-shadow: 0 2px 12px rgba(0, 0, 0, 0.3);

  /* ===== 图片消息：去掉边框 ===== */
  --image-msg-border: none;
  --image-me-border: none;
  --image-them-border: none;

  /* ===== 转账卡片：去掉边框 ===== */
  --transfer-card-border: none;
  --transfer-me-card-border: none;
  --transfer-them-card-border: none;
}

